import copy, unittest
from wednesday_stale_week_gate import check,GateError,schedule_digest
class TestGate(unittest.TestCase):
    def setUp(self):
        self.target=dict(operation="WEDNESDAY_FREEZE",season=2026,week=11,cutoff_at="2026-11-18T16:00:00Z")
        self.schedule=dict(season=2026,updatedAt="2026-11-18T15:00:00Z",weeks=[dict(week=11,games=[dict(id="101",date="2026-11-19T20:00:00Z",home="H",away="A")])])
        self.draft=dict(season=2026,week=11,generatedAt="2026-11-18T15:30:00Z",games=copy.deepcopy(self.schedule["weeks"][0]["games"]))
        self.shadow=copy.deepcopy(self.draft);self.shadow["status"]="EXPERIMENTAL_SHADOW_ONLY"
        self.authority=dict(status="VERIFIED_EXTERNAL",season=2026,week=11,cutoff_at=self.target["cutoff_at"],verified_at="2026-11-18T15:30:00Z")
        self.pin()
    def pin(self):self.authority["schedule_sha256"]=schedule_digest(self.schedule)
    def reject(self,code):
        with self.assertRaises(GateError) as ctx:check(self.target,self.schedule,self.draft,self.shadow,self.authority)
        self.assertEqual(ctx.exception.code,code)
    def test_matching(self):self.assertEqual(check(self.target,self.schedule,self.draft,self.shadow,self.authority),("101",))
    def test_both_stale(self):self.draft["week"]=self.shadow["week"]=8;self.reject("STALE_WEEK_INPUT")
    def test_one_stale(self):self.shadow["week"]=8;self.reject("STALE_WEEK_INPUT")
    def test_game_id_mismatch(self):self.shadow["games"][0]["id"]="102";self.reject("GAME_ID_MISMATCH")
    def test_game_metadata_mismatch(self):self.shadow["games"][0]["home"]="OTHER";self.reject("GAME_METADATA_MISMATCH")
    def test_post_cutoff_schedule(self):self.schedule["updatedAt"]="2026-11-18T18:57:31Z";self.pin();self.reject("POST_CUTOFF_SCHEDULE")
    def test_post_cutoff_input(self):self.draft["generatedAt"]="2026-11-18T16:01:00Z";self.reject("POST_CUTOFF_INPUT")
    def test_missing_week(self):self.target["week"]=12;self.reject("UNTRUSTED_TARGET_WEEK")
    def test_duplicate_ids(self):self.schedule["weeks"][0]["games"].append(copy.deepcopy(self.schedule["weeks"][0]["games"][0]));self.pin();self.reject("INVALID_SCHEDULE_IDS")
    def test_wrong_operation(self):self.target["operation"]="GRADE";self.reject("INVALID_OPERATION")
    def test_invalid_shadow_status(self):self.shadow["status"]="OFFICIAL";self.reject("INVALID_SHADOW_STATUS")
    def test_target_season_mismatch(self):self.target["season"]=2025;self.reject("UNTRUSTED_TARGET_WEEK")
    def test_missing_authority(self):self.authority=None;self.reject("MISSING_SCHEDULE_AUTHORITY")
    def test_forged_authority_label(self):self.authority["status"]="UNVERIFIED";self.reject("MISSING_SCHEDULE_AUTHORITY")
    def test_stale_target_bypass(self):self.target["week"]=self.draft["week"]=self.shadow["week"]=8;self.reject("UNTRUSTED_TARGET_WEEK")
    def test_schedule_tamper(self):self.schedule["weeks"][0]["games"][0]["home"]="X";self.reject("SCHEDULE_PROVENANCE_MISMATCH")
    def test_duplicate_week(self):self.schedule["weeks"].append(copy.deepcopy(self.schedule["weeks"][0]));self.pin();self.reject("DUPLICATE_OR_MISSING_WEEK")
    def test_other_duplicate_week(self):self.schedule["weeks"] += [dict(week=12,games=[]),dict(week=12,games=[])];self.pin();self.reject("DUPLICATE_SCHEDULE_WEEK")
    def test_kickoff_at_cutoff(self):self.schedule["weeks"][0]["games"][0]["date"]=self.target["cutoff_at"];self.pin();self.reject("GAME_NOT_FUTURE_AT_CUTOFF")
    def test_invalid_kickoff(self):self.schedule["weeks"][0]["games"][0]["date"]="bad";self.pin();self.reject("INVALID_TIMESTAMP")
    def test_naive_kickoff(self):self.schedule["weeks"][0]["games"][0]["date"]="2026-11-19T20:00:00";self.pin();self.reject("INVALID_TIMESTAMP")
    def test_authority_verified_after_cutoff(self):self.authority["verified_at"]="2026-11-18T16:01:00Z";self.reject("POST_CUTOFF_SCHEDULE")
    def test_empty_home(self):self.schedule["weeks"][0]["games"][0]["home"]="";self.pin();self.reject("INVALID_GAME_METADATA")
    def test_mismatched_cutoff(self):self.target["cutoff_at"]="2026-11-18T17:00:00Z";self.reject("UNTRUSTED_TARGET_WEEK")
    def test_unverified_operation_grade(self):self.target["operation"]="HISTORICAL_GRADE";self.reject("INVALID_OPERATION")
if __name__=="__main__":unittest.main()
